INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16801, 'Isaiah 13:4', 'Isaiah', 13, 4, '&nbsp;په غرونو باندې شور ته غوږ ونيسئ، د خلقو لوئې ګڼې آوازونو ته غوږ ونيسئ، د قومونو او د بادشاهو د خلقو د راغونډېدو آواز ته غوږ ونيسئ. مالِک خُدائ ربُ الافواج د جنګ دپاره لښکر تياروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16802, 'Isaiah 13:5', 'Isaiah', 13, 5, '&nbsp;هغوئ د لرې لرې مُلکونو او د دُنيا د سرونو نه راځى. دوئ د مالِک خُدائ وسله ده چې د هغۀ غصه څرګنده کړى او هغه ټول مُلک برباد کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16803, 'Isaiah 13:6', 'Isaiah', 13, 6, '&nbsp;ژاړئ او فريادونه کوئ. د مالِک خُدائ د قيامت ورځ رانزدې ده، هغه ورځ رانزدې ده چې په هغه ورځ به قادر خُدائ تباهى راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16804, 'Isaiah 13:7', 'Isaiah', 13, 7, '&nbsp;د هر يو کس لاسونه به کار پرېږدى او ټول خلق به بې‌حوصلې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16805, 'Isaiah 13:8', 'Isaiah', 13, 8, '&nbsp;هغوئ ټول به ويريږى په دردونو کښې به راګېر شى، داسې دردونه به وى لکه چې د يوې ښځې ماشوم پېدا کيږى. هغوئ به په يره يره کښې يو بل ته ګورى او د يرې په وجه به د هغوئ مخونه زېړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16806, 'Isaiah 13:9', 'Isaiah', 13, 9, '&nbsp;ګورئ، د مالِک خُدائ ورځ راروانه ده، د هغۀ د سخت قهر او غصې يوه سخته ورځ راروانه ده. د زمکې نه به بيابان جوړ شى او هر يو ګناهګار به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16807, 'Isaiah 13:10', 'Isaiah', 13, 10, '&nbsp;ټول ستورى او د ستورو قبيلې به ځلېدل بس کړى، نمر چې راخېژى نو دا به تور وى او د سپوږمۍ رڼا به ختمه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16808, 'Isaiah 13:11', 'Isaiah', 13, 11, '&nbsp;مالِک خُدائ وفرمائيل، ”د دُنيا د بدۍ له وجې به زۀ دې له سزا ورکړم، او بدعمله خلقو له به د هغوئ د ګناهونو سزا ورکړم. زۀ به د مغرورانو غرور ختم کړم، او د ظالمانو لوئى به خاورې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16809, 'Isaiah 13:12', 'Isaiah', 13, 12, '&nbsp;زۀ به انسانان د خالص سرو زرو نه زيات ناياب کړم، او خلق به د اوفير د سرو زرو نه هم لږ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16810, 'Isaiah 13:13', 'Isaiah', 13, 13, '&nbsp;په هغه ورځ چې زۀ مالِک خُدائ ربُ الافواج خپله غصه څرګندوم نو زۀ به آسمانونه ولړزوم او زمکه به د خپل ځائ نه وخوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16811, 'Isaiah 13:14', 'Isaiah', 13, 14, '&nbsp;په بابل کښې به خلق داسې منډې وهى لکه چې هوسۍ د ښکاريانو نه منډې وهى يا ګډې د شپون نه بغېر روانې وى، او هغوئ به خپل وطن او خپل قوم ته واپس د تلو کوشش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16812, 'Isaiah 13:15', 'Isaiah', 13, 15, '&nbsp;هر څوک چې ګېر شى په تُوره به ووهلے شى، او هر څوک چې ونيولے شى نو په تُوره باندې به ووژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16813, 'Isaiah 13:16', 'Isaiah', 13, 16, '&nbsp;د هغوئ د سترګو په وړاندې به د هغوئ د بچو نه په وهلو وهلو باندې ساه وويستلے شى او د هغوئ کورونه به لوټ کړے شى او د هغوئ د ښځو سره به په زور زنا وشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16814, 'Isaiah 13:17', 'Isaiah', 13, 17, '&nbsp;مالِک خُدائ وفرمائيل، ”زۀ ميديانيان راپارومه چې په بابل باندې حمله وکړى، ځکه چې هغوئ نۀ د سپينو زرو پرواه ساتى او نۀ هغوئ دپاره سرۀ زر څۀ معنىٰ لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16815, 'Isaiah 13:18', 'Isaiah', 13, 18, '&nbsp;هغوئ به د خپلو غشو او ليندو سره زلمى ووژنى. هغوئ به په تې رَودُونکو ماشومانو او په نورو ماشومانو هيڅ رحم او ترس نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16816, 'Isaiah 13:19', 'Isaiah', 13, 19, '&nbsp;د ټولو نه ښائسته بادشاهى د بابل ده، د هغې ځائ خلق په بابل باندې فخر کوى. خو مالِک خُدائ به بابل هغه شان تباه کړى لکه څنګه چې يې سدوم او عموره تباه کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16817, 'Isaiah 13:20', 'Isaiah', 13, 20, '&nbsp;هلته به بيا هيڅ څوک هم نۀ اوسيږى. دا به بيا کله هم آباد نۀ شى. نۀ به عرب هلته خېمې لګوى او نۀ به شپانۀ خپلې رَمې ودروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16818, 'Isaiah 13:21', 'Isaiah', 13, 21, '&nbsp;دا به يو داسې ځائ وى چرته چې ځنګلى ځناور اوسيږى او چرته چې ګونګا خپلې جالې جوړوى. هلته به شتر‌مرغ اوسيږى او ځنګلى چېلۍ به په هغه کنډرو کښې ټوپونه وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16819, 'Isaiah 13:22', 'Isaiah', 13, 22, '&nbsp;د دې په مينارو او محلونو کښې به د ځنګلى سپو او د ګيدړانو آوازونه وى. د بابل وخت رارسېدلے دے. او د دې وخت تقريباً د ختمېدو والا دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16820, 'Isaiah 14:1', 'Isaiah', 14, 1, '&nbsp;خو مالِک خُدائ به يو ځل بيا د يعقوب په اولاد باندې رحم وکړى، او اِسرائيل به بيا خپل غوره شوے قوم وګڼى. هغه به هغوئ واپس راولى چې په خپل مُلک کښې بيا آباد شى او د پردى مُلک خلق به راځى او د هغوئ سره به په اتفاق اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16821, 'Isaiah 14:2', 'Isaiah', 14, 2, '&nbsp;ډېر قومونه به د بنى اِسرائيلو مدد وکړى چې هغوئ خپل هغه مُلک ته واپس راشى کوم چې مالِک خُدائ هغوئ له ورکړے دے. او هلته به هغه قومونه د وينځو او نوکرانو په توګه د بنى اِسرائيلو خِدمت کوى. کومو خلقو چې په يو وخت کښې بنى اِسرائيليان نيولى وُو نو اوس به بنى اِسرائيليان هغه خلق ونيسى او د بنى اِسرائيلو خلق به په هغه خلقو حکومت کوى چا چې په يو وخت کښې په هغوئ ظلم زياتے کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16822, 'Isaiah 14:3', 'Isaiah', 14, 3, '&nbsp;په هغه ورځ به مالِک خُدائ تاسو له د تکليفونو او پرېشانو نه آرام درکړى او د هغه سخت کار نه به مو خلاص کړى چې د ستاسو نه په زور اخستے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16823, 'Isaiah 14:4', 'Isaiah', 14, 4, '&nbsp;نو تاسو به د بابل بادشاه پورې ټوقې کوئ او وايئ به چې، ”هغه ظالم بادشاه غورزېدلے دے. او د هغۀ غصه ختمه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16824, 'Isaiah 14:5', 'Isaiah', 14, 5, '&nbsp;مالِک خُدائ د بدعملو طاقت ختم کړے دے او د حکمرانانو اختيار يې مات کړے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16825, 'Isaiah 14:6', 'Isaiah', 14, 6, '&nbsp;چا چې به په غصه کښې په خلقو باندې ظلم زياتے کولو او چې هغوئ کوم قومونه فتح کړى وُو نو د هغوئ خِلاف يې هيڅکله ظلم نۀ بس کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16826, 'Isaiah 14:7', 'Isaiah', 14, 7, '&nbsp;نو په آخر کښې به ټوله دُنيا د امن او سکون نه خوند اخلى او هر طرف ته به د خوشحالۍ سندرې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16827, 'Isaiah 14:8', 'Isaiah', 14, 8, '&nbsp;د سبر ونې او د لبنان د دِيار ونې په هغه بادشاه باندې خوشحاله دى چې د چا بادشاهى ختمه شوې ده، ځکه چې داسې څوک نشته چې دا ونې ووهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16828, 'Isaiah 14:9', 'Isaiah', 14, 9, '&nbsp;د مړو دُنيا بادشاه ته د پخير راغلې دپاره خپل ځان تياروى. کوم کسان چې په دُنيا کښې طاقتور وُو نو د هغوئ روحونه به بادشاه ته ودريږى. د بادشاهانو روحونه به د هغوئ د تختُونو نه ستا ليدو ته ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16829, 'Isaiah 14:10', 'Isaiah', 14, 10, '&nbsp;هغوئ ټول به هغۀ ته آواز وکړى چې تۀ هم زمونږ په شان کمزورے يې. تۀ هم زمونږ په شان يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16830, 'Isaiah 14:11', 'Isaiah', 14, 11, '&nbsp;ستا شان او شوکت تا سره ښخ شوے دے، او ستا د بينجو ساز خاموش شوے دے. تۀ د وړو چينجو په بستره ملاست يې او د چينجو په کمبله پټ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16831, 'Isaiah 14:12', 'Isaiah', 14, 12, '&nbsp;اے ځلېدونکى ستوريه، اے د سحر زويه. اوس د آسمان نه راپرېوتے يې. په تېره زمانه کښې تا قومونه فتح کول، خو اوس تۀ په خاوره کښې غورزولے شوے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16832, 'Isaiah 14:13', 'Isaiah', 14, 13, '&nbsp;تا په زړۀ کښې وئيل چې بره آسمان ته به وخېژم او په اوچتو ستورو به خپل تخت ولګوم، په شمال کښې به په هغه غر د يو بادشاه په شان کښېنم چرته چې معبودان راغونډيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16833, 'Isaiah 14:14', 'Isaiah', 14, 14, '&nbsp;تا ووئيل چې پاس وريځو ته به وخېژم او د خُدائ تعالىٰ په شان به شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16834, 'Isaiah 14:15', 'Isaiah', 14, 15, '&nbsp;خو تۀ لاندې د مړو د دُنيا هغه د ټولو نه ژورې کندې ته ويشتلے شوے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16835, 'Isaiah 14:16', 'Isaiah', 14, 16, '&nbsp;څوک هم چې تا ووينى نو هغوئ به غور سره تا ته ګورى او سوچ به کوى چې، ولې دا هغه سړے دے چا چې زمکه خوځوله او بادشاهۍ به يې لړزولې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16836, 'Isaiah 14:17', 'Isaiah', 14, 17, '&nbsp;ولې دا هم هغه سړے دے چا چې ښارونه تباه کړل او دُنيا يې په بيابان بدله کړه؟ ولې دا هغه سړے دے چې هغۀ هيڅکله هم خپل قېديان نۀ آزادول چې خپلو کورونو ته لاړ شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16837, 'Isaiah 14:18', 'Isaiah', 14, 18, '&nbsp;د دُنيا ټول بادشاهان په خپلو ښائسته ښائسته قبرونو کښې پراتۀ دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16838, 'Isaiah 14:19', 'Isaiah', 14, 19, '&nbsp;ستا خو قبر هم نشته او لاش دې لکه د بې‌کاره څانګې په شان بهر غورزولے شوے دے. ستا لاش د فوجيانو په هغه لاشونو کښې پټ دے کوم چې په جنګ کښې وژلے شوى دى. او تۀ د هغوئ سره د کاڼو يوې کندې ته غورزولے شوے يې او د پښو لاندې کړے شوے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16839, 'Isaiah 14:20', 'Isaiah', 14, 20, '&nbsp;ستا جنازه به د نورو بادشاهانو په شان عزت سره نۀ کيږى، ځکه چې تا خپل مُلک تباه کړے دے او خپل خلق دې وژلى دى. د بدعمله کس اولاد به هيڅکله هم د عزت سره نۀ ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16840, 'Isaiah 14:21', 'Isaiah', 14, 21, '&nbsp;د دې سړى زامن ووژنئ، پرېږدئ چې د هغوئ د پلار نيکۀ د ګناه په وجه مړۀ شى. داسې نۀ وى چې هغوئ بيا په دُنيا باندې فتح حاصله کړى او دُنيا د هغوئ د ښارونو نه ډکه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16841, 'Isaiah 14:22', 'Isaiah', 14, 22, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى، ”زۀ پخپله د بابل خلاف راوچت شوے يم. زۀ به د دوئ اولاد تباه او برباد کړم. ما، مالِک خُدائ دا وئيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16842, 'Isaiah 14:23', 'Isaiah', 14, 23, '&nbsp;بابل به زۀ په نمژنه زمکه بدل کړم او هلته به ګونګا مارغان اوسيږى. زۀ به په بابل باندې داسې جارُو ووهم چې هغه به د ځان سره هر څۀ جارُو کړى. زۀ، مالِک خُدائ، ربُ الافواج دا اعلان کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16843, 'Isaiah 14:24', 'Isaiah', 14, 24, '&nbsp;مالِک خُدائ ربُ الافواج دا قسم کړے دے، ”ما چې کومه منصوبه جوړه کړې ده نو هغه به پوره شى. ما چې د څۀ اراده کړې ده نو هغه به کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16844, 'Isaiah 14:25', 'Isaiah', 14, 25, '&nbsp;زۀ به په خپل مُلک اِسرائيل کښې اسوريان تباه کړم او زۀ به هغوئ په خپلو غرونو کښې د پښو لاندې کړم. د هغوئ جغ به زما د خلقو نه اخوا شى او بوج به د هغوئ د اوږو نه اوچت شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16845, 'Isaiah 14:26', 'Isaiah', 14, 26, '&nbsp;د ټولې دُنيا دپاره دا زما منصوبه ده او ما خپل لاس د ټولو قومونو خلاف اوچت کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16846, 'Isaiah 14:27', 'Isaiah', 14, 27, '&nbsp;مالِک خُدائ ربُ الافواج دا فېصله کړې ده، نو څوک دا رد کولے شى؟ هغۀ خپل لاس اوچت کړے دے، څوک دا رايسارولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16847, 'Isaiah 14:28', 'Isaiah', 14, 28, '&nbsp;دا پېغام په هغه کال باندې راغلے وو په کوم کال چې احاز بادشاه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16848, 'Isaiah 14:29', 'Isaiah', 14, 29, '&nbsp;اے فلستيانو، په دې باندې خوشحالېږئ مۀ چې په کومه چوکه به تاسو وهل خوړل هغه ماته شوې ده، ځکه چې د دغه مار نه به زيات زهرژن مار پېدا شى، يوه داسې اژدها چې تاسو به تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16849, 'Isaiah 14:30', 'Isaiah', 14, 30, '&nbsp;غريبانان به خوراک وکړے شى او ضرورتمند به په محفوظ ځائ کښې آرام وکړے شى. خو ستاسو بېخ به د سخت قحط سره ختم کړم او چې کوم ژوندى پاتې شى هغوئ به تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16850, 'Isaiah 14:31', 'Isaiah', 14, 31, '&nbsp;اے د ښار دروازو ژاړئ. اے ښاره ماتم کوه. اے فلستيانو د يرې نه رپېږئ. د شمال طرف نه د لوږى په شان وريځ راروانه ده، دا د داسې فوجيانو لښکر دے چې په صفونو کښې يې يو بُزدل هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16851, 'Isaiah 14:32', 'Isaiah', 14, 32, '&nbsp;د فلستيه نه چې کوم پېغام وړُونکى مونږ له راځى نو هغوئ له څۀ جواب ورکړُو؟ مونږ به ورته وايو چې مالِک خُدائ صيون د دې دپاره محفوظ کړے دے، چې د هغۀ په خلقو کښې مظلومان هلته پناه واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16852, 'Isaiah 15:1', 'Isaiah', 15, 1, '&nbsp;دا پېغام د موآب په حقله دے. په يوه شپه د موآب ښار عار تباه شوے دے. په يوه شپه د موآب ښار قير تباه شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16853, 'Isaiah 15:2', 'Isaiah', 15, 2, '&nbsp;د ديبون خلق غر ته ختلى دى چې په خپله عبادتخانه کښې ژړا وکړى. د موآب خلق به د نبو او ميدبا په ښارونو د خفګان نه ژړا کوى، هغوئ د خفګان نه خپل سرونه او ږيرې کلې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16854, 'Isaiah 15:3', 'Isaiah', 15, 3, '&nbsp;په لارو کوڅو کښې خلقو د ټاټ جامې اغوستې دى، د ښار په چوکونو کښې او د کورونو په چتونو باندې خلق ژړا او ماتم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16855, 'Isaiah 15:4', 'Isaiah', 15, 4, '&nbsp;د حسبون او اِلى‌عالى خلق په ژړا دى او د هغوئ ژړا تر يهض پورې اورېدے شى. د موآب فوجيان په يره کښې نعرې وهى، او هغوئ بې‌حوصلې شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16856, 'Isaiah 15:5', 'Isaiah', 15, 5, '&nbsp;زما زړۀ د موآب دپاره ژاړى. خلق د ضُعر ښار او عجلت‌شليشياه ښار ته تښتېدلى دى. خلق په ژړا کښې د لوحيت په طرف خېژى، هغوئ د حورونايم په لار په چغو چغو ژاړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16857, 'Isaiah 15:6', 'Isaiah', 15, 6, '&nbsp;د نِمريم اوبۀ اوچې شوې دى او د دې واښۀ اوچ شوى دى ټول شينکے ختم شوے دے او يو شين بوټے هم پاتې نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16858, 'Isaiah 15:7', 'Isaiah', 15, 7, '&nbsp;نو په دې وجه خلق د خپل ټول مال دولت او سامان سره خاروَلو د وادۍ نه تېريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16859, 'Isaiah 15:8', 'Isaiah', 15, 8, '&nbsp;د موآب د حد ټولو پولو سره د ژړا آوازونه راتمبيږى. دا ژړا د اجلائم او بير ايليم په ښارونو کښې اورېدلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16860, 'Isaiah 15:9', 'Isaiah', 15, 9, '&nbsp;د ديبون ښار سره سيند په وينه باندې سور دے او خُدائ پاک به د هغه ځائ په خلقو باندې د هغې نه هم زيات مصيبت راولى. ازمرى به په هغوئ حمله وکړى چې څوک د موآب نۀ بچ وتې وى او په هغوئ هم څوک چې لا په مُلک کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16861, 'Isaiah 16:1', 'Isaiah', 16, 1, '&nbsp;د سلع نه د مُلک حکمران ته په کلنګ کښې ګډُورى ورولېږه. دا د صحرا په لاره د صيون لور غرۀ ته ورولېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16862, 'Isaiah 16:2', 'Isaiah', 16, 2, '&nbsp;د موآب ښځې د ارنون سيند په غاړه باندې د هغه مارغانو په شان دى چې د جالې نه شړلے شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16863, 'Isaiah 16:3', 'Isaiah', 16, 3, '&nbsp;هغوئ ژاړى او وائى، ”زمونږ مدد وکړئ، زمونږ دشمنانو نه زمونږ حِفاظت وکړئ. د هغوئ د حملې نه مونږ بچ کړئ. اوس چې مونږ راتښتېدلى يُو نو مونږ سره دوکه مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16864, 'Isaiah 16:4', 'Isaiah', 16, 4, '&nbsp;زمونږ مهاجر پرېږدئ چې ستاسو په مُلک کښې ايسار شى. څوک چې هغوئ تباه کول غواړى هغوئ نه ورله پناه ورکړئ.“ ظلم زياتے او تباهى به ختم شى او څوک چې د نقصان رسولو کوشش کوى نو هغوئ به مخ د زمکې نه ورک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16865, 'Isaiah 16:5', 'Isaiah', 16, 5, '&nbsp;بيا به د داؤد د اولاد يو کس بادشاه شى او هغه به په وفادارۍ او مينې سره په خلقو باندې حکومت کوى. هغه به په صحيح کار کولو کښې تېزى کوى او ګورى به چې د اِنصاف نه کار اخستے شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16866, 'Isaiah 16:6', 'Isaiah', 16, 6, '&nbsp;مونږ د موآب د غرور په حقله اورېدلى دى. هغوئ مغروره، کبرژن، خود غرضه او سپين سترګې دى. خو د هغوئ لاپې عبث دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16867, 'Isaiah 16:7', 'Isaiah', 16, 7, '&nbsp;د موآب خلق په خپل حال باندې ژاړى، هغوئ په سلګو سلګو د قير‌حراست ښار کشمش يادوى، د هغوئ حالت بدترين دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16868, 'Isaiah 16:8', 'Isaiah', 16, 8, '&nbsp;د حسبون پټى او د سبماه د انګورو باغونه تباه شوى دى، دا د انګورو هغه باغونه وُو چې د شرابو سره به يې د قومونو حکمرانان نشه کېدل. په يو وخت کښې د يعزير ښار پورې او په صحرا کښې نمرخاتۀ طرف ته او نمرپرېواتۀ طرف ته د مړ درياب بلې غاړې پورې د دې څانګې رسېدلې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16869, 'Isaiah 16:9', 'Isaiah', 16, 9, '&nbsp;خو اوس زۀ د سبماه د انګورو باغونو دپاره هم هغه شان ژاړم لکه څنګه چې د يعزير دپاره ژاړم. د حسبون او اِلى‌عالى دپاره زما اوښکې توئيږى، ځکه چې د فصل لَو نۀ کيږى چې خلق ورسره خوشحاله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16870, 'Isaiah 16:10', 'Isaiah', 16, 10, '&nbsp;د باغونو نه خندا او خوشحالى غېبه شوې ده. د انګورو په باغونو کښې يو کس هم آوازونه نۀ کوى او نۀ سندرې وائى. هيڅ څوک هم انګور نۀ چخڼى کوى چې رس ترېنه وباسى، ولې چې ما د خندا نعرې ختمې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16871, 'Isaiah 16:11', 'Isaiah', 16, 11, '&nbsp;زړۀ مې لکه د رباب په ساز کښې د موآب د غمه چوى، او زما زړۀ د قير‌حراست دپاره غمژن دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16872, 'Isaiah 16:12', 'Isaiah', 16, 12, '&nbsp;د موآب خلق هسې خپل ځانونه ستړى کوى او هغوئ په غرونو باندې زيارتونو او خپلو عبادتخانو ته د سوال دپاره ځى، دا به دوئ له هيڅ فائده ورنۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16873, 'Isaiah 16:13', 'Isaiah', 16, 13, '&nbsp;دا هغه پېغام وو چې مالِک خُدائ د موآب په حقله مخکښې ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16874, 'Isaiah 16:14', 'Isaiah', 16, 14, '&nbsp;او اوس مالِک خُدائ فرمائى، ”پوره په درې کاله کښې به د موآب لوئ مال دولت ختم شى. او د دې د ډېرو خلقو نه به صرف يو څو ژوندى پاتې شى، او هغوئ به ډېر کمزورى وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16875, 'Isaiah 17:1', 'Isaiah', 17, 1, '&nbsp;دا د دمشق په حقله پېغام دے، ”د دمشق ښار به تباه شى، او دا به تش د کنډرو يو ډېرے پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16876, 'Isaiah 17:2', 'Isaiah', 17, 2, '&nbsp;د عروعير ښارونه به د همېشه دپاره په کنډرو بدل شى. دا به د ګډو او څاروو دپاره د څرن زمکه وګرځى، چې هيڅ څوک به يې ترې نه نۀ شړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16877, 'Isaiah 17:3', 'Isaiah', 17, 3, '&nbsp;د اِسرائيل پاخۀ ښارونه به تباه شى او د دمشق بادشاهى به ختمه شى. کوم شاميان چې ژوندى پاتې وى نو هغوئ به د بنى اِسرائيلو په شان د شرم سره مخ شى. ما مالِک خُدائ، ربُ الافواج دا فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16878, 'Isaiah 17:4', 'Isaiah', 17, 4, '&nbsp;په هغه ورځ به د اِسرائيل دبدبه ختمه شى او د دې مالدارى به په غريبۍ بدله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16879, 'Isaiah 17:5', 'Isaiah', 17, 5, '&nbsp;اِسرائيل به د يو داسې پټى په شان وى چې غله ترې نه رېبلے شوې او راغونډه کړے شوې وى، دا به داسې وى لکه چې د رفائيم په وادۍ کښې يو پټے شاړ پروت وى او چې د دې نه هر څۀ وړلے شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16880, 'Isaiah 17:6', 'Isaiah', 17, 6, '&nbsp;خو صرف يو څو کسان به پاتې شى او اِسرائيل به د زيتُونو د داسې ونې په شان وى چې د هغې نه ټول زيتون راټول کړے شوى وى خو صرف دوه درې دانې يې په آخرى سر باندې او يا يو څو يې په لاندې څانګو کښې پاتې وى. ما مالِک خُدائ د بنى اِسرائيلو خُدائ پاک دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16881, 'Isaiah 17:7', 'Isaiah', 17, 7, '&nbsp;په هغه وخت به خلق په خپل خالِق بهروسه کوى، او هغوئ به د بنى اِسرائيلو په مقدس ذات منحصر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16882, 'Isaiah 17:8', 'Isaiah', 17, 8, '&nbsp;هغوئ چې په خپلو لاسونو کومې قربان‌ګاه جوړې کړې دى هغوئ به په دې باندې نور يقين نۀ ساتى، او د اشيرې بُت په نښو او د خوشبودارو مصالحو سوزولو په قربان‌ګاه باندې به يې اعتبار ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16883, 'Isaiah 17:9', 'Isaiah', 17, 9, '&nbsp;په هغه وخت به د هغوئ پاخۀ ښارونه شاړ او ويجاړ شى او د هغه ښارونو په شان به په کنډرو بدل شى لکه څنګه چې حِويانو او اموريانو په هغه وخت کښې پرېښى وُو چې هغوئ د بنى اِسرائيلو نه تښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16884, 'Isaiah 17:10', 'Isaiah', 17, 10, '&nbsp;افسوس، تاسو خپل د خلاصون خُدائ پاک هېر کړے دے او هغه مضبوط ګټ درته نۀ دے ياد چې تاسو پرې پناه اخستے شئ. خو تاسو د پردى مُلک د معبود د عبادت دپاره ښائسته باغونه کَرلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16885, 'Isaiah 17:11', 'Isaiah', 17, 11, '&nbsp;خو چې کله تاسو کَرلى وى نو کۀ هم په هغه سحر دا غوټۍ او ګلونه هم شى، نو هيڅ پېداوار به يې نۀ وى. تشه بيمارى او لاعلاجه درد به درته ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16886, 'Isaiah 17:12', 'Isaiah', 17, 12, '&nbsp;بې‌شمېره قومونه د سمندر د شور په شان شور کوى، هغوئ داسې شور کوى لکه چې لوئې لوئې چپې په خپلو کښې جنګيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16887, 'Isaiah 17:13', 'Isaiah', 17, 13, '&nbsp;اګر کۀ هغوئ د سمندر د تېزو چپو په شان شور کوى، خو خُدائ پاک به هغوئ خاموش کړى او هغوئ به وتښتى. هغوئ به داسې تښتى لکه څنګه چې هوا بوس زغلى، يا څنګه چې دوړې په طوفان کښې الوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16888, 'Isaiah 17:14', 'Isaiah', 17, 14, '&nbsp;په ماښام کښې به اِسرائيل سخت ويريږى، خو تر سحره به د هغوئ ټول دشمنان مړۀ وى. دا به د هغوئ قسمت او اَنجام وى چې څوک زمونږ د لوټ کولو کوشش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16889, 'Isaiah 18:1', 'Isaiah', 18, 1, '&nbsp;په هغه مُلک افسوس په کوم کښې چې د وزر آواز اورېدلے شى، او چرته چې د ايتهوپيا سيندونه بهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16890, 'Isaiah 18:2', 'Isaiah', 18, 2, '&nbsp;د هغه مُلک نه د نيل درياب ته سفيران په داسې کشتو کښې ځى چې د لوخو نه جوړې وى. اے تېزو پېغام وړونکو، ځئ. هغه لوړو لوړو او د هوارې څرمنې خلقو له پېغام يوسئ د چا نه چې ټوله دُنيا يريږى، هغه مضبوط او جنګيالى قوم له پېغام يوسئ، د چا مُلک چې په سيندونو باندې تقسيم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16891, 'Isaiah 18:3', 'Isaiah', 18, 3, '&nbsp;څوک چې په زمکه اوسيږى نو هغوئ ټول دا واورئ. هغه نښې ته وګورئ چې د غرونو په سرونو به ښکاره شى. او چې بيګل غږيږى نو غوږ ورته ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16892, 'Isaiah 18:4', 'Isaiah', 18, 4, '&nbsp;مالِک خُدائ ما ته وفرمائيل، ”زۀ به خپل د استوګنې ځائ نه په خاموشۍ سره ګورمه. خو زما دا خاموشى به داسې وى لکه د تکڼې غرمې د شُغلې په شان يا د لَو په وخت د سحر د پرخې په شان.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16893, 'Isaiah 18:5', 'Isaiah', 18, 5, '&nbsp;د انګورو راټولولو نه مخکښې، کله چې دا ټول ګلونه وغورزوى او انګور په پخېدو وى، نو مالِک خُدائ به حبشيان داسې په آسانۍ سره تباه کړى لکه چې د بوټو قينچيانې د انګورو د بوټى نه څانګې پرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16894, 'Isaiah 18:6', 'Isaiah', 18, 6, '&nbsp;د هغوئ د فوجيانو لاشونه به مارغانو او ځنګلى ځناورو ته پراتۀ وى. په اوړى کښې به هغوئ د مارغانو خوراک وى او په ژمى کښې به د ځناورو خوراک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16895, 'Isaiah 18:7', 'Isaiah', 18, 7, '&nbsp;يو وخت به هغه مضبوط او جنګيالى قومونه چې اوچت او هوارې څرمنې دى، د چا نه چې ټوله دُنيا يريږى مالِک خُدائ ربُ الافواج ته به د هغه مُلک نه نذرانې راوړى، کوم مُلک چې په سيندونو باندې تقسيم شوے دے. هغوئ به د صيون ښار ته راشى، چرته چې مالِک خُدائ ربُ الافواج استوګنه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16896, 'Isaiah 19:1', 'Isaiah', 19, 1, '&nbsp;دا پېغام د مِصر په حقله دے. ګورئ، مالِک خُدائ مِصر ته د تېزې وريځې دپاسه راروان دے. د مِصريانو بُتان د هغۀ په وړاندې لړزيږى او د مِصر خلق خپله حوصله بائيلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16897, 'Isaiah 19:2', 'Isaiah', 19, 2, '&nbsp;مالِک خُدائ فرمائى، ”زۀ به په مِصر کښې خانه جنګى راولم نو ورور به د ورور خِلاف شى او ګاونډى به د ګاونډى خِلاف شى. ښار به د ښار خِلاف شى او بادشاهى به د بادشاهۍ خِلاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16898, 'Isaiah 19:3', 'Isaiah', 19, 3, '&nbsp;مِصريان به حوصله بائيلى او زۀ به د هغوئ منصوبې ګډې وډې کړم. هغوئ به د بُتانو، د مړو د روحونو والا نه او فالګرو نه مشورې اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16899, 'Isaiah 19:4', 'Isaiah', 19, 4, '&nbsp;زۀ به مِصر يو ظالم مالِک ته حواله کړم، يو طاقتور بادشاه به په هغوئ حکومت کوى. ما مالِک خُدائ، ربُ الافواج دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16900, 'Isaiah 19:5', 'Isaiah', 19, 5, '&nbsp;د نيل په درياب کښې به اوبۀ کمې شى او درياب به مکمل اوچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');